  'settings.connections.type': 'Mota',
  'settings.connections.typeHint': '«Bat ere ez» eta «Zuzena» ez dira lerro bera. Bat ere ez geldia da: ez du konexiorik izendatzen eta ez da inoiz erabiltzen, beraz bete arte baino ez du irauten. Zuzena benetako aukera da: makina honen lerrotik ateratzea eta behean izendatutako ostalarientzat proxy oro nahita saihestea; horrela uzten da NAS bat aplikazio osoari ezarritako proxy batetik kanpo. Iragazkia ostalariarekin bat datorren lerroak iragazkirik gabeko lerroa gainditzen du, beraz iragazkidun zuzeneko lerroak beti irabazten dio dena hartzen duen proxy bati.',
