  'settings.rules.var.match': 'Arau honen FIELD eremuko «ereduarekin bat dator» ereduaren N. harrapaketa-taldea. Hau JDownloader-en <jd:source:N> da, zein eredu irakurtzen duen esaten duen izenarekin. Eremu horretan bat datorren eredurik ez duen arau bat gordetzean baztertzen da, isilean <jd:match:url:1> izeneko karpeta sortu beharrean.',
