  'settings.reconnect.command': 'Programa',
  'settings.reconnect.commandHint': 'Abiaraziko den programaren bide osoa. Zuzenean abiarazten da, ez shell baten bidez, beraz hodi bat, birbideratze bat edo bata bestearen atzetik doazen bi komando «Script» metodoari dagozkio. %%router%%, %%username%%, %%password%% eta %%ip%% abiatu aurretik ordezkatzen dira.',
  'settings.reconnect.args': 'Argumentuak',
