  'settings.reconnect.upnpState': 'Ez da besterik behar. Atebidea sareari galdetuz aurkitzen da, eta horrexegatik da hau bideratzaileari buruz ezer jakin gabe dabilen metodoa.',
  'settings.reconnect.upnpLocation': 'Atebidearen deskribapen URLa',
  'settings.reconnect.upnpLocationHint': 'Aukerakoa, eta normalean hutsik. Bete ezazu multidifusio bilaketa iragazten den baina atebidea bera ezin hobeto iristen den lekuetan bakarrik; hori aurkikuntzak berak ezin du inoiz konpondu.',

  'settings.reconnect.interpreter': 'Interpretatzailea',
  'settings.reconnect.interpreterHint': 'Scripta ematen zaion programa, bide osoarekin: /bin/sh, /bin/bash, /usr/bin/python3.',
  'settings.reconnect.interpreterArgs': 'Interpretatzailearen argumentuak',
  'settings.reconnect.interpreterArgsHint': 'Lerro bakoitzeko bat, script fitxategiaren aurretik jartzen dira. Normalean hutsik.',
  'settings.reconnect.script': 'Scripta',
  'settings.reconnect.scriptHint': 'Aldi baterako fitxategi pribatu batean idazten da, eta interpretatzaileari haren bidea ematen zaio, beraz hemengo ezer ez da inoiz komiletan komando lerro batera iristen. Aldagaiak fitxategia idatzi baino lehen ordezkatzen dira, hau da, kutxa honetan idatzitako pasahitza fitxategi horretara iristen da: %%password%% erabilita pasahitzaren eremuan geratzen da.',

  'settings.reconnect.router': 'Bideratzailearen helbidea',
  'settings.reconnect.routerHint': 'Zure sareko bideratzailea, eskemarik gabe: 192.168.1.1, ez http://192.168.1.1/. Horretara zabaltzen da %%router%%. Ez da helbide publikoa, eta biak ez dira inoiz nahastu behar: publikora bidalitako saio-hasiera eskaera batek zure bideratzailearen pasahitza internetera bidaltzen du.',
