  'settings.reconnect.policy': 'Noiz gertatzen den bere kabuz',
  'settings.reconnect.policyHint': 'Birkonexio automatikoak leku bakar batetik abiarazten dira, eta orri hau ez da leku hori. Bat abiatzen da deskarga motorrak berak itxaronaldi baten ondoren beste saiakera bat eskatzen duenean, horrela esaten baitu ostalari batek muga helbide honi lotuta dagoela. Ilara geldirik dagoen bitartean ez da inoiz exekutatzen, bideratzailea berrabiarazteak oraindik martxan dauden deskargak eteten baititu. Birkonexioa erabat konfiguratuta ez dagoen bitartean ere ez da inoiz exekutatzen. Aldi berean bat bakarrik dabil: bigarren eskaera batek lehenengoaren epaia itxaroten du, bideratzailearengatik harekin borrokatu beharrean. Eta helbidea mugitzen ez bada, ez da ezer aurreratzen eta ohiko saiakera arteko itxaronaldiari bere bidea egiten uzten zaio.',

