  'settings.chunks': 'Konexioak deskarga bakoitzeko (0 = automatikoa)',
  'settings.chunksHint': 'Deskarga batek zenbat konexio irekitzen dituen zehatzagorik ezer ez denean aplikatzen. Arau batek, edo deskarga bakar batek, bere zenbakia eman dezake eta honi gailentzen zaio. Gutxiago jasaten duen ostalariak gutxiago jasoko du hala ere: ostalariaren mugak zenbakia jaitsi baino ezin du egin, inoiz ez igo. 0 jarrita aplikazioak erabakitzen du. Eskukada bat baino konexio gehiagok ez du ezer ekartzen fitxategiz fitxategi mugatzen duen ostalari batean, eta kontu bat markatuta gera dadin bide segurua da.',
  'task.chunks': 'Konexioak (0 = ezarpen orokorra)',
  'task.chunksHint': 'Deskarga honek zehazki zenbat konexio irekitzen dituen. Ezarpen orokorrari eta hura ezarri duen edozein arauri gailentzen zaio, baina inoiz ez ostalariari: gutxiago jasaten duen ostalariak gutxiago jasoko du hala ere. 0 jarrita salbuespena kentzen da eta zenbakia berriro kanpoan erabakitzen da.',
  'columns.connection': 'Konexioa',

  'props.title': 'Propietateak',
  'props.mixed': 'Hainbat balio',
  'props.mixedHint': 'Errenkada hauek ez datoz bat, horregatik dago laukia hutsik. Ukitu gabe ez du ezer aldatzen; idatzi bertan eta hautatutako errenkada bakoitzak idatzitakoa jasoko du.',
  'props.name': 'Izena',
  'props.nameHint': 'Fitxategi izen bat, inoiz ez bide bat: karpetak zehazten dituen guztia izen bakar batera mozten da. Amaitutako deskarga diskoan ere berrizendatzen da, zerrendak eta karpetak elkarri kontra egin ez diezaioten. Martxan dagoenak bere motorrak irekita duen fitxategia gordetzen du eta izen berria amaitzean hartzen du. Hasi ez denak berehala hartzen du. Izena fitxategi bakar batena da, beraz lauki hau errenkada bakar baterako baino ez da eskaintzen.',
  'props.comment': 'Oharra',
  'props.commentHint': 'Esteka honi buruzko zure oharra. Gorde eta zerrendan erakusten da; aplikazioan ez du ezer eragiten.',
  'props.priority': 'Lehentasuna',
  'props.priorityHint': 'Altuagoa lehenago abiatzen da. Oraindik zain dagoena berrantolatzen du; jada martxan den deskarga ez da ilarara itzultzen.',
  'props.autoExtract': 'Erauzi artxiboak',
  'props.autoExtractHint': 'Deskarga amaitutakoan artxiboa deskonprimatzen den ala ez. „Heredatu“ aukerak erabakia artxiboen ezarpen orriari uzten dio, eta hori ez da „itzalita“ bezalakoa. Etengailua deskonprimatzeko unean irakurtzen da, beraz orain pizten baduzu, lehenago amaitutakoa ere deskonprimatuko da.',
  'props.inherit': 'Heredatu',
  'props.on': 'Piztuta',
  'props.off': 'Itzalita',

  'strip.label': 'Deskargen baturak',
