  'strip.hint': 'Ekarritako byteak zor direnen aurrean. Amaitutako, huts egindako eta bildu besterik egin ez diren estekak baturatik kanpo geratzen dira, eta baita ostalariak tamaina esan ez duen guztia ere - hor asmakizun bat inork ezer egin ezin duen zenbakia litzateke.',
  'strip.scope': 'Zenbakiek zer hartzen duten',
