  'settings.access.relay.title': 'Proiektuaren errelea',
  'settings.access.relay.body': 'Errelea bitartekari bat da, zure instantzia guztiak etxeko saretik kanpo ere, hau da, edonondik, iristeko modukoak egiten dituena. Hau proiektuak doan eskaintzen du.',
  'settings.access.relay.use': 'Proiektuaren errelea erabili',
  'settings.access.relay.leadProject': 'Ezer konfiguratu gabe dabil. Zure instantziek elkarri esaten dioten guztia zifratuta doa, eta gakoa zuk bakarrik duzu.',
  'settings.access.relay.address': 'Helbidea',
  'settings.access.relay.seesButton': 'Zer ikusten du?',
  'settings.access.relay.seesTip': 'Erreleak ez du ikusten: zure estekak, zure deskargak, zure fitxategiak eta zure sarbide-tokena.\n\nErreleak ikusten du: zure instantzien IP helbideak eta noiz bidaltzen duten zerbait.\n\nHori ezin da zifratuz ezkutatu. Traba egiten badizu, erabili zeure errele bat.',
  'settings.access.relay.none': 'Errelerik ez',
  'settings.access.relay.noneHint': 'Ez dago errelerik aktibo. Sare berean, hau da, etxean, instantziek elkar aurkitzen jarraitzen dute berez. Sare desberdinen artean ez dira elkarrengana iristen, beraz ez dago urruneko sarbiderik.',
  'settings.access.relay.own': 'Norberaren errelea',
  'settings.access.relay.project': 'Proiektuaren errelea',
  'settings.access.relay.whichHint': '{address} bidez doa',
  'settings.access.relay.savedProject': 'Proiektuaren errelea aktibo dago',
  'settings.access.relay.savedOwn': 'Zure errelea aktibo dago',
  'settings.access.relay.savedOff': 'Errelea itzalita',
  'settings.access.ownRelay.title': 'Zure errelea',
  'settings.access.ownRelay.body': 'Erabili zeure errelea proiektuarenaren ordez.',
  'settings.access.ownRelay.use': 'Nire errelea erabili',
  'settings.access.ownRelay.lead': 'Bi bide: instantzia hau bera da errelea, edo helbide bat sartzen duzu.',
  'settings.access.ownRelay.serveLabel': 'Erabili instantzia hau errele gisa',
  'settings.access.ownRelay.serveHint': 'Instantzia hau kanpotik iristeko modukoa bada baino ez du funtzionatzen, adibidez Nginx Proxy Manager eta zeure domeinu baten bidez.',
  'settings.access.ownRelay.serveClients': '{count} konektatuta une honetan.',
  'settings.access.ownRelay.addressLabel': 'Helbidea',
  'settings.access.ownRelay.addressPlaceholder': 'adib. https://relay.nireduomeinua.eus',
  'settings.access.ownRelay.save': 'Gorde',
  'settings.access.ownRelay.everyInstance': 'Helbide hau instantzia honentzat bakarrik da. Sartu instantzia guztietan.',
  'settings.access.ownRelay.containerLabel': 'Edukiontzi propio gisa',
  'settings.access.ownRelay.containerHint': 'Zure instantziarik ez bada kanpotik iristeko modukoa, erreleak beste nonbait egon behar du: zure zerbitzarian edo VPS txiki batean. Instalatu edukiontzia Unraid Community Applications bildumatik edo beheko aginduarekin.\n\nEdukiontziak ez du konfiguraziorik behar: abiarazi, idatzi haren helbidea goian, eta kito. Ez du ezer gordetzen, beraz ez dago babeskopiarik egiteko.',
  'settings.access.tokens.title': 'API token-ak',
  'settings.access.tokens.intro':
    'Script, nabigatzaile-hedapen edo telefono baterako izendun kredentzialak. Bakoitza bere kabuz indargabetu daiteke, beste bezero guztiek erabiltzen duten partekatutako pasahitza aldatu gabe.',
