  'settings.access.identity.title': 'Instantzia honen identitatea',
  'settings.access.identity.nameLabel': 'Izena',
  'settings.access.identity.namePlaceholder': 'adib. Etxeko zerbitzaria',
  'settings.access.identity.nameHint': 'Parekatzean eta beheko QR kodean lehenengo eskaintzen da, sistema eragileak edo edukiontziaren exekuzio-inguruneak makina honi ematen dion izenaren ordez. Aukerakoa - utzi hutsik izen hori erabiltzen jarraitzeko.',
  'settings.access.identity.domainsLabel': 'Ezagutzen diren domeinuak',
  'settings.access.identity.domainsHint': 'Automatikoki gogoratzen da haren bidez benetan lehen eskaera iristen den unean, hemen zerrendatuta jarraitzeko baita geroagoko eskaerak LANeko IPtik iristen direnean ere. Gehitu bat eskuz jadanik konfiguratuta dagoen baina oraindik bisitatu ez den domeinu baterako - helbide oso bat lerroko, adib. https://kl.example.com.',
  'settings.access.cardTitle': 'Instantziak konektatzea eta urruneko sarbidea',
  'settings.access.phrase.body': 'Esaldi bakar batek zure KnightLoader guztiak lotzen ditu. Sortu hemen eta itsatsi beste instantzietan - konturik gabe, saio-hasierarik gabe, ezer konfiguratu beharrik gabe.',
  'settings.access.phrase.noPasswordWarning': 'Instantzia honek ez du pasahitzik. Esaldiak harekin konektatzen duzun instantzia oro irekitzen du, beraz hemen irakur dezakeenak guztietara iristen da, ez honetara soilik. Hobe goian pasahitz bat jartzea lehenik.',
  'settings.access.phrase.activate': 'Sortu esaldia',
  'settings.access.phrase.howLead': 'Hamabi hitz, besterik ez. Hona zer egin behar duzun, eta zer gertatzen den:',
  'settings.access.phrase.howStep1': 'Instantzia honetan, sakatu "{button}". Hamabi hitz agertuko dira.',
  'settings.access.phrase.howStep2': 'Ireki KnightLoader beste makinan, etorri orri honetara, sakatu "{button}" eta idatzi hamabi hitzak.',
  'settings.access.phrase.howStep3': 'Egina! Instantzia bakoitza bestearen «Instantziak» atalean agertzen da orain, eta edozein erabil dezakezu edozeinetatik. Errelea piztuta, zure instantziak zure saretik kanpotik ere iristen dira.',
  'settings.access.phrase.howWhat': 'Hitzak sekretu bat dira, ez helbide bat. Instantzia bakoitzak bi gako ateratzen ditu haietatik: bat besteak aurkitzeko, bestea zifratzeko.\n\nElkar aurkitzeko, instantzia bakoitzak berak deitzen dio interneteko topagune berari. Gako bera erakusten duena elkartzen da. Horregatik ez du zure instantziarik kanpotik iristeko modukoa izan behar.\n\nTopaguneak ezin du irakurri. Zure hitzak ez ditu inoiz ikusten, eta handik igarotzen den guztia bigarren gakoarekin zifratuta dago.',
  'settings.access.phrase.statusDisconnected': 'Konektatu gabe',
  'settings.access.phrase.statusHintProject': 'Proiektuaren errelera konektatuta. Urruneko sarbidea prest dago.',
  'settings.access.phrase.statusHintOwn': 'Zeure errelera konektatuta. Urruneko sarbidea prest dago.',
  'settings.access.phrase.statusHintOff': 'Ez dago errelerik aktibo. Zure instantziak sare lokalean baino ez dira iristen.',
  'settings.access.phrase.statusHintLost': 'Ez dago errelearekin konexiorik. KnightLoader saiatzen jarraitzen du. Ordura arte instantziak sare lokalean baino ez dira elkartzen.',
  'settings.access.phrase.statusConnected': 'Konektatuta',
  'settings.access.phrase.howButton': 'Nola funtzionatzen du honek?',
  'settings.access.phrase.joinButton': 'Sartu esaldia',
  'settings.access.phrase.joinPlaceholder': 'Itsatsi beste instantziaren hamabi hitzak',
  'settings.access.phrase.joinConfirm': 'Konektatu',
  'settings.access.phrase.errChecksum': 'Esaldi hau ez da baliozkoa - begiratu hitzen bat gaizki idatzita edo lekuz aldatuta dagoen.',
  'settings.access.phrase.errUnknownWord': '{position}. hitza ("{word}") ez dago onartutako hitzen artean.',
  'settings.access.phrase.errWordCount': '{count} hitz dira - esaldi batek {need} behar ditu.',
  'settings.access.phrase.yourPhrase': 'Zure konexio-esaldia',
  'settings.access.phrase.pasteHint': 'Itsatsi hamabi hitz hauek konektatu nahi duzun beste instantzia bakoitzean.',
  'settings.access.phrase.qrHint': 'Edo eskaneatu hau beste gailutik, idatzi beharrean.',
  'settings.access.phrase.revealWhy': 'Esaldia berriro erakusteko, sartu instantzia honen pasahitza. Taldeko instantzia guztiak irekitzen ditu, ez hau bakarrik.',
