  'settings.access.intakePortsHint': 'Instantzia honetara zuzenean iristeko beste bide batzuk, ohiko saio-hasitik kanpo - bakoitzak bere eskuragarritasuna hemen erakutsita.',
  'settings.nav.browsertools': 'Nabigatzailea eta aplikazioa',
  'settings.browsertools.bookmarkletStep1': 'Arrastatu beheko botoia zure nabigatzailearen laster-marken barrara - beste edozein laster-marka bezala gordetzen da, ez da ezer instalatzen.',
  'settings.browsertools.bookmarkletStep2': 'Edozein orritan, egin klik gainean (aukeratu testua aurretik hori bakarrik nahi baduzu). KnightLoader fitxa txiki bat irekiko da orri horren estekarekin, edo aukeratutako testuarekin, jada beteta - berrikusi eta gehitu handik deskarga gisa.',
  'settings.browsertools.installLabel': 'Nola instalatu',
