  'settings.browsertools.installChromiumStep5': 'Egin klik helbide-barraren ondoko puzzle-pieza ikonoan eta ainguratu KnightLoader: Chromek ez ditu luzapen berriak barran jartzen bere kabuz.',
  'settings.browsertools.installFirefoxStep1': 'Betiko instalatzeko: ireki about:addons eta egin klik goiko eskuineko engranaje ikonoan.',
