  'settings.nav.resolvers': 'Ebazleak',
  'settings.module.ytdlp': 'yt-dlp',
  'settings.resolvers.moduleUnavailable': 'Modulua ez dago erabilgarri',
  'settings.resolvers.moduleUnavailableHint': 'Beheko guztia gordetzen da hala ere, eta yt-dlp erabilgarri dagoen unean bertan hasiko da eragina izaten - orain bertan editatzeak ez du ezer galtzen.',
  'settings.resolvers.intro': 'yt-dlp atzealdearen konfigurazioa; berak onartzen dituen multimedia- eta zuzeneko emanaldi-guneak eskuratzen ditu. Esteka jakin bat zein zerbitzuk kudeatzen duen - yt-dlp, debrid kontu bat, buruzagirik gabeko JD sidecar-a - Kontuak orriko bideratze-ordenaren arabera erabakitzen da; hemen esteka jadanik yt-dlp-ra bideratu ondoren honek egiten duena bakarrik azaltzen da.',
  'settings.resolvers.quality': 'Kalitatea',
  'settings.resolvers.qualityHint': 'yt-dlp abiaraztean zein -f hautatzaile erabiltzen den. Erabilgarri dagoen onena yt-dlp-ren berezko lehenetsia da, eta ezarpen hau existitu aurretik deskarga bakoitzak erabiltzen zuena.',
  'settings.resolvers.quality.best': 'Erabilgarri dagoen onena',
