  'settings.resolvers.subtitleLangsHint': 'yt-dlp-ren berezko --sub-langs balioa, adib. en,de. Hutsik badago, en izango da lehenetsia.',
  'settings.resolvers.subtitleAuto': 'Eskuz jarritako pistarik ez dagoenean, automatikoki sortutako azpitituluak ere eskuratu',
  'settings.resolvers.outputTitle': 'Irteerako fitxategiaren izena',
  'settings.resolvers.outputHint': 'yt-dlp-ren berezko -o txantiloia. Hutsik badago, txertatutako %(title)s.%(ext)s erabiltzen da. Azpikarpetak izan ditzake, adib. %(uploader)s/%(title)s.%(ext)s.',

  'settings.nav.torrents': 'Torrentak',
  'settings.module.torrents': 'Torrentak',
  'settings.torrents.title': 'Torrentak',
  'settings.torrents.subtitle': 'Seed helburuak, transferentzia mugak, ataka birbideratzea eta DHT/PEX magnet estekentzako eta .torrent fitxategientzako.',
  'settings.torrents.seedingTitle': 'Seed',
  'settings.torrents.seedRatio': 'Helburuzko seed ratioa',
  'settings.torrents.seedRatioHint': 'Amaitutako torrent bati seed egiten jarraitzen dio, bere tamainarekiko proportzio hori enjanbrera itzuli arte. 0 = ratio helbururik ez.',
  'settings.torrents.seedDuration': 'Helburuzko seed iraupena',
  'settings.torrents.seedDurationHint': 'Amaitutako torrent bati seed egiten jarraitzen dio amaitu ondoren denbora horretan. 0 = denbora mugarik ez. Goiko bi helburuetatik lehena lortzean gelditzen da seed egitea.',
  'settings.torrents.seedDurationUnit': 'ordu',
