  'settings.torrents.uploadLimit': 'Igotze muga',
  'settings.torrents.uploadLimitHint': 'Torrent batek seed egiten duen bitartean enjanbrera zein abiaduratan igotzen duen mugatzen du. 0 = mugarik gabe.',
  'settings.torrents.uploadLimitUnit': 'KiB/s',
  'settings.torrents.portTitle': 'Ataka eta birbideratzea',
  'settings.torrents.port': 'Ataka',
  'settings.torrents.portHint': 'Instantzia honek enjanbrearen konexioak entzuten dituen ataka. 0 balioak torrent motorrak bere kabuz aukeratzea eragiten du.',
  'settings.torrents.portMapHint': 'Bideratzaileari eskatzen dio goiko ataka UPnP bidez makina honetara birbideratzeko, beste bideratzaile baten atzean dauden peerrek ere hura lortu ahal izateko. Bideratzaile guztiek ez dute hau onartzen, eta batzuek eskaera onartzen dute benetan funtzionatu gabe.',
  'settings.torrents.portMapButton': 'UPnP birbideratzea saiatu',
  'settings.torrents.portMapping': 'Bideratzaileari galdezka…',
  'settings.torrents.portMapNeedsPort': 'Ezarri ataka bat goian birbideratu aurretik - 0 denean, bideratzaileak ez du nora birbideratu.',
  'settings.torrents.portMapConfirmed': 'Berretsita: {port} ataka birbideratuta dago eta eskuragarri dagoela egiaztatu da.',
  'settings.torrents.portMapUnconfirmed': 'Bideratzaileak eskaera onartu du, baina ezin izan da berretsi birbideratzeak benetan funtzionatzen duenik. Bideratzaile batzuek isilean egiten dute hau - saiatu konektibitate egiaztapen bat sarearen kanpotik.',
  'settings.torrents.portMapFailed': 'Ezin izan da ataka birbideratu: {error}',
  'settings.torrents.portMapUnavailable': 'Bertsio honek oraindik ez du ataka birbideratzerik eskaintzen.',
  'settings.torrents.networkTitle': 'Peer aurkikuntza',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Peerrak aurkitzen ditu trackerrik gabe, beste BitTorrent bezeroak zerrenda banatu gisa erabiliz.',
  'settings.torrents.pex': 'Peer trukea (PEX)',
  'settings.torrents.pexHint': 'Ezagutzen diren peerrak jadanik konektatutakoekin trukatzen ditu, peer gutxi dituen enjanbre bat azkarrago aurki dadin.',
  'settings.torrents.privateNote': 'Torrent pribatu batek biak automatikoki desaktibatzen ditu bere metadatuak ezagutu bezain laster, hemen ezarritakoa edozein dela ere - igotako .torrent fitxategi baten kasuan berehala, edo magnet esteka baten metadatu propioak enjanbretik iritsi bezain laster. Tracker pribatu gehienek edozein erabiltzen duten kontuak debekatzen dituzte.',
  'settings.torrents.engineNote': 'Helburuzko seed ratioa, helburuzko seed iraupena eta ataka motor honek abiarazitako torrent guztietara iristen dira jada - ataka, ordea, instantzia hau azkenekoz abiarazi zenetik abiarazitako lehen torrentera bakarrik, motorraren berezko torrent bezeroa behin bakarrik eraikitzen baita eta gero ez baita inoiz berreraikitzen; geroagoko gordetzeak, hala ere, zuzen gordetzen jarraitzen du eta hurrengo berrabiaraztetik aurrera indarrean sartzen da. Igotze muga oraindik gorde eta balioztatu bakarrik egiten da, motorrak oraindik ez baitu abian den deskarga batera aplikatzeko modurik. Beheko DHT eta PEX egoera berean daude torrent arrunt (ez-pribatu) baten kasuan: instantzia honen berezko balio lehenetsia ere ez da oraindik abian den deskarga batera iristen, beraz torrent batek biak piztuta jarraitzen du seed egiten, hemen ezarritakoa edozein dela ere - torrent pribatu bat erabat beste kasu bat da, ikus beheragoko oharra. Hala ere, beheragoko birbideratze botoiak zerbait erreala egiten du: goian idatzitako ataka zenbakia birbideratzeko eskatzen dio bideratzaileari zintzotasunez, torrentik une honetan entzuten ari den ala ez kontuan hartu gabe.',
