  'onboarding.step': '{n}. urratsa / {total}',
  'onboarding.skip': 'Saltatu',
  'onboarding.back': 'Atzera',
  'onboarding.next': 'Hurrengoa',
  'onboarding.finish': 'Hasi KnightLoader erabiltzen',
  'onboarding.welcome.title': 'Ongi etorri KnightLoader-era',
  'onboarding.welcome.body': 'KnightLoader auto-ostatatutako deskarga-kudeatzaile bat da: itsatsi edo askatu esteka bat, eta benetan kudeatzen duen backend-ak eskuratuko du - fitxategi-esteka arruntetarako barneko motorra, yt-dlp multimedia-orrietarako, dagoeneko ordaintzen duzun ostalari baterako debrid zerbitzu bat, edo interfazerik gabeko JDownloader gainerako guztirako. Bira labur honek hasi baino lehen egiaztatzea merezi duen ezarpen bakarra biltzen du.',
  'onboarding.welcome.langLabel': 'Interfazearen hizkuntza',
  'onboarding.folder.title': 'Non egon behar dute fitxategiek?',
  'onboarding.folder.body': 'Hau da amaitutako deskargak idazten diren karpeta. Idatzi bide bat edo arakatu zerbitzaria bat aukeratzeko - edonoiz alda dezakezu berriro Ezarpen orokorren orritik.',
  'onboarding.accounts.title': 'Premium ostalariak, nahi dituzunean',
  'onboarding.accounts.body': 'Ilarak kontu barik ere funtzionatzen du. Dagoeneko ordaintzen duzun ostalari edo debrid zerbitzu batean abiadura osoa nahi duzunean, gehitu haren saioa Kontuak atalean - ez dago orain hemen ezer konfiguratu beharrik.',
