  'settings.nav.shortcuts': 'Lasterbideak',
  'settings.shortcuts.subtitle': 'Berezko teklatu-lasterbidea duten komando guztiak, non aplikatzen diren arabera taldekatuta. Aldatu esleipen bat, edo berrezarri berezkora.',
  'settings.shortcuts.empty': 'Oraindik komando batek ere ez du berezko lasterbiderik.',
  'settings.shortcuts.change': 'Aldatu',
  'settings.shortcuts.reset': 'Berrezarri',
  'settings.shortcuts.resetAll': 'Berrezarri denak berezkora',
  'settings.shortcuts.resetAllConfirmTitle': 'Lasterbide guztiak berrezarri?',
  'settings.shortcuts.resetAllConfirmBody': 'Berresleitutako lasterbide bakoitza bere berezkora itzuliko da. Hau ezin da desegin.',
  'settings.shortcuts.resetAllConfirm': 'Berrezarri denak',
  'settings.shortcuts.captureTitle': 'Sakatu lasterbide berri bat «{name}»(r)entzat',
  'settings.shortcuts.captureHint': 'Sakatu tekla-konbinazio bat, edo Escape uzteko.',
