  'settings.downloads.collectorTitle': 'Biltzailea',
  'settings.downloads.diskTitle': 'Diskoko lekua',
  'settings.downloads.diskHint': 'Hiru zenbaki, deskargak diskoa bete aurretik atxikitzeko, eta ez ondoren. Hirurak deskarga idazten ari den diskoan libre dauden byteak dira, beraz lan-karpeta beste disko batean badago, hura neurtzen da. Zeroak dagokion zenbakia itzaltzen du. Kontuan izan zer ezin duen egin: sistema guztiei ezin zaie galdetu zenbat leku dagoen libre, eta erantzunik ez dagoen tokian ez da inoiz ezer atxikitzen, ez dakienean blokeatzen duen zaindari batek erabat osasuntsu dagoen makina bat geldiaraziko bailuke.',
