  'settings.headerProfiles.delete': 'Ezabatu profila',
  'settings.headerProfiles.deleteConfirm': '{id} profila ezabatu? Barruan dituen goiburuak desagertu egingo dira, eta {origin} gunetik egiten diren deskargak berriro haiek gabe bidaliko dira.',
  'settings.rules.action.category': 'Kategoria',
  'settings.rules.action.categoryHint': 'Bat datozen estekak Kategoriak orriko tiraderetako batean sailkatzen ditu, eta tiradera horrek bere karpeta, bere ilarako lekua, bere erauzteko etengailua eta bere talka-araua dakartza berekin. Ukitu gabe utzita, arau honek ez du horri buruz iritzirik eta esteka sailkatu gabe geratzen da. Arau honek deskargen karpeta bat ere izendatzen badu, karpeta horrek irabazten du eta tiraderak gainerako guztia jartzen du. Ezabatuta dagoen tiradera bat izendatzea gordetzean baztertzen da, ez dagoen tiradera bati begira dagoen arau batek ez baitu ezertxo ere egiten bat datorren esteka bakoitzarekin, mezurik eman gabe.',
  'settings.rules.action.categoryNone': 'Oraindik ez dago kategoriarik. Sortu bat lehenik Kategoriak orrian; bestela arau honek existitzen ez den tiradera batean sailkatuko lituzke estekak.',
