  'detail.label': 'Zereginaren xehetasunak',
  'detail.link': 'Esteka',
  'detail.address': 'Helbidea',
  'detail.addressHint': 'Deskarga hau zein helbidetatik abiatu zen. Aplikazioak eskatu zuena da, eta hori ez da beti byteak nondik etorri diren: debrid zerbitzu baten bidez, beheko ostalaria fitxategia dagoen gunea da, eta backenda fitxategia ekarri duena.',
  'detail.copy': 'Kopiatu',
  'detail.copied': 'Kopiatuta',
