  'views.label': 'Gordetako ikuspegiak',
  'views.save': 'Gorde ikuspegi hau',
  'views.saveHint': 'Ikuspegi bat orain ezarrita dituzun bilaketa eta iragazkiak dira, zuk aukeratutako izen baten azpian gordeta. Zutabeak eta ordenatzea ez dira horren parte, horiek beren aldetik gogoratzen dira.',
