  'views.tooBig': 'Ikuspegi honek gorde daitezkeenak baino iragazki-balio gehiago ditu. Kendu marka batzuk alboko barran eta gorde berriro.',
  'views.manage': 'Kudeatu gordetako ikuspegiak',
